/**
 * Unit tests for TimeSeries.clone()
 */
public class TimeSeries_clone_TriageGen0Test {

    @Test
    public void testCloneEmptySeries() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");

        TimeSeries clone = (TimeSeries) series.clone();

        assertNotSame("Clone should be a different object", series, clone);
        assertEquals("Clone should have same name", series.getName(), clone.getName());
        assertEquals("Clone should be empty", 0, clone.getItemCount());
        assertEquals("Clone should have same domain description", series.getDomainDescription(), clone.getDomainDescription());
        assertEquals("Clone should have same range description", series.getRangeDescription(), clone.getRangeDescription());
    }

    @Test
    public void testCloneWithItems() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");
        series.setDomainDescription("Domain");
        series.setRangeDescription("Range");

        // Adding dummy data using a simple implementation or mock if available. 
        // Since we don't have the implementation of RegularTimePeriod, 
        // we assume a standard implementation exists in the classpath or use a mock.
        // For this test, we use a generic approach.

        // Note: In a real environment, one would use a concrete RegularTimePeriod implementation.
        // Assuming the existence of a way to add data:
        series.add(new MockTimePeriod(1000L), 10.0);
        series.add(new MockTimePeriod(2000L), 20.0);

        TimeSeries clone = (TimeSeries) series.clone();

        assertNotSame("Clone should be a different object", series, clone);
        assertEquals("Clone should have same item count", series.getItemCount(), clone.getItemCount());
        assertEquals("Clone should have same name", series.getName(), clone.getName());
        assertEquals("Clone should have same domain description", series.getDomainDescription(), clone.getDomainDescription());
        assertEquals("Clone should have same range description", series.getRangeDescription(), clone.getRangeDescription());

        // Verify data integrity
        for (int i = 0; i < series.getItemCount(); i++) {
            assertEquals("Value at index " + i + " should match", series.getValue(i), clone.getValue(i));
            assertEquals("Period at index " + i + " should match", series.getTimePeriod(i), clone.getTimePeriod(i));
        }
    }

    @Test
    public void testCloneDeepCopyProperties() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");
        series.setMaximumItemCount(100);
        series.setMaximumItemAge(500L);

        TimeSeries clone = (TimeSeries) series.clone();

        assertEquals("Clone should have same max item count", series.getMaximumItemCount(), clone.getMaximumItemCount());
        assertEquals("Clone should have same max item age", series.getMaximumItemAge(), clone.getMaximumItemAge());

        // Ensure modifying clone doesn't affect original
        clone.setMaximumItemCount(200);
        assertNotEquals("Modifying clone max count should not affect original", series.getMaximumItemCount(), clone.getMaximumItemCount());
    }

    /**
     * Inner class to facilitate testing without external dependencies on specific RegularTimePeriod implementations.
     */
    private static class MockTimePeriod extends RegularTimePeriod {
        private final long millis;
        public MockTimePeriod(long millis) { this.millis = millis; }
        @Override public long getStart() { return millis; }
        @Override public long getEnd() { return millis + 1000; }
        @Override public boolean isLeapYear(int year) { return false; }
        @Override public int getYear() { return 2023; }
        @Override public int getMonth() { return 1; }
        @Override public int getDay() { return 1; }
        @Override public int getHour() { return 0; }
        @Override public int getMinute() { return 0; }
        @Override public int getSecond() { return 0; }
        @Override public int getMillisecond() { return 0; }
        @Override public boolean equals(Object obj) { 
            return obj instanceof MockTimePeriod && ((MockTimePeriod)obj).millis == this.millis; 
        }
        @Override public int hashCode() { return Long.hashCode(millis); }
    }
}
